 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [derive (Debug , Parser)] enum Commands { # [doc = " Scan a directory for macros and produce a report"] Scan { # [doc = " Path to scan"] # [arg ()] path : Option < PathBuf > , # [doc = " Scan all local dependencies in the workspace"] # [arg (short , long)] workspace : bool , # [doc = " Output file for the report"] # [arg (short , long , default_value = "report.json")] output : PathBuf , } , # [doc = " Split macros from a report file into separate files"] Split { # [doc = " Path to the report.json file"] # [arg ()] report_path : PathBuf , # [doc = " Output directory for macros"] # [arg (short , long , default_value = "output/macros")] output : PathBuf , } , }